def halted(p, label):
    R = json.load(open(p)); assert R["self_sha256"] == BTP_SHA, f"bt_p_reading sha {p}"
    runs = list(R["runs"].values()); assert len(runs) == 1
    b = runs[0]["bases"]["FULL_RECIPE window start @ 2023-06-30T04:00:00Z"]; pp = b["per_path"]; assert len(pp) == NPATH
    return {"receipt": p, "receipt_sha256": sha(p), "halted_paths": int(sum(1 for x in pp if x["fired"])), "n_paths": len(pp),
            "window_last_anchor": pp[0]["window_last_anchor"], "label": label}
